1	// solver.mjs: E8 order fulfilment with compensation (SPEC-E.md).
2	//
3	// Each tick rebuilds what is due from the carry, the events that arrived and the
4	// outcome of earlier effects. Effect keys come from ids, so an effect is emitted
5	// once; it is re-issued only after a 400 (invalid request) or an unknown outcome
6	// that the platform did not commit. Times are epoch milliseconds in the carry and
7	// ISO 8601 with the Europe/Amsterdam offset in the output.
8	
9	const MIN = 60_000;
10	const FINAL = new Set(['completed', 'failed', 'cancelled']);
11	const FUL_ORDER = ['pending', 'unavailable', 'processing', 'dispatched', 'completed', 'failed', 'cancelled'];
12	
13	// ---------- time ----------
14	const fmtAms = new Intl.DateTimeFormat('en-GB', {
15	  timeZone: 'Europe/Amsterdam', hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',
16	  hour: '2-digit', minute: '2-digit', second: '2-digit',
17	});
18	const pad = n => String(n).padStart(2, '0');
19	const T = v => (typeof v === 'number' ? v : Date.parse(v));
20	
21	function isoAms(t) {
22	  const base = Math.floor(t / 1000) * 1000;
23	  const g = {};
24	  for (const p of fmtAms.formatToParts(new Date(base))) g[p.type] = p.value;
25	  const local = Date.UTC(+g.year, +g.month - 1, +g.day, +g.hour, +g.minute, +g.second);
26	  const off = Math.round((local - base) / MIN);
27	  const a = Math.abs(off);
28	  return `${g.year}-${g.month}-${g.day}T${g.hour}:${g.minute}:${g.second}${off < 0 ? '-' : '+'}${pad(Math.floor(a / 60))}:${pad(a % 60)}`;
29	}
30	const dayOf = t => isoAms(t).slice(0, 10);
31	
32	// Order ids as the spec normalises them: trim, drop leading '#', upper-case.
33	const normId = s => String(s ?? '').trim().replace(/^#+/, '').trim().toUpperCase();
34	
35	// ---------- files: ctx.files holds the rulebook, master data and api files (JSON or CSV) ----------
36	function listFiles(ctx) {
37	  const f = ctx.files;
38	  try {
39	    if (f instanceof Map) return [...f.keys()];
40	    if (Array.isArray(f)) return f.map(x => (typeof x === 'string' ? x : x.path));
41	    if (typeof f?.list === 'function') return f.list('') || [];
42	    if (f && typeof f === 'object') return Object.keys(f);
43	  } catch { /* no listing: no editions visible */ }
44	  return [];
45	}
46	
47	function parseCsv(text) {
48	  const lines = text.split(/\r?\n/).filter(l => l.trim() !== '');
49	  if (lines.length === 0) return [];
50	  const head = lines[0].split(',').map(s => s.trim());
51	  return lines.slice(1).map(l => {
52	    const cells = l.split(',').map(s => s.trim());
53	    return Object.fromEntries(head.map((h, i) => [h, cells[i]]));
54	  });
55	}
56	
57	function load(ctx, path) {
58	  const f = ctx.files;
59	  let v;
60	  try {
61	    if (typeof f === 'function') v = f(path);
62	    else if (typeof f?.read === 'function') v = f.read(path);
63	    else if (typeof f?.get === 'function') v = f.get(path);
64	    else if (f instanceof Map) v = f.get(path);
65	    else if (f && typeof f === 'object') v = f[path];
66	  } catch { return undefined; }
67	  if (v && typeof v === 'object' && typeof v.content === 'string') v = v.content;
68	  if (typeof v !== 'string') return v;
69	  if (path.endsWith('.csv')) return parseCsv(v);
70	  try { return JSON.parse(v); } catch { return undefined; }
71	}
72	
73	// Rows of a table: an array, the first array inside an object, or an object keyed by id.
74	function rows(x) {
75	  if (Array.isArray(x)) return x;
76	  if (!x || typeof x !== 'object') return [];
77	  const arr = Object.values(x).find(Array.isArray);
78	  if (arr) return arr;
79	  return Object.entries(x).map(([k, v]) => (v && typeof v === 'object' ? { _key: k, ...v } : { _key: k, _value: v }));
80	}
81	const firstOf = (r, names) => {
82	  for (const n of names) if (r && r[n] != null) return r[n];
83	  return undefined;
84	};
85	
86	function pickEdition(ctx, t) {
87	  const day = dayOf(t);
88	  let best = null;
89	  for (const p of listFiles(ctx)) {
90	    const m = /^rulebook\/([^/]+)\/edition\.json$/.exec(p);
91	    if (!m) continue;
92	    const e = load(ctx, p) || {};
93	    const from = String(e.effectiveFrom ?? '').slice(0, 10);
94	    if (from && from <= day && (!best || from > best.from)) best = { dir: m[1], from, id: e.id ?? m[1] };
95	  }
96	  return best;
97	}
98	
99	function priceMap(ctx) {
100	  const m = {};
101	  for (const r of rows(load(ctx, 'master/catalog.json'))) {
102	    m[String(firstOf(r, ['sku', '_key']))] = Number(firstOf(r, ['unitPriceMinor', 'priceMinor', '_value'])) || 0;
103	  }
104	  return m;
105	}
106	
107	function feeMap(ctx, dir) {
108	  const m = {};
109	  for (const r of rows(load(ctx, `rulebook/${dir}/shipping-fees.json`))) {
110	    m[String(firstOf(r, ['location', '_key']))] = Number(firstOf(r, ['feeMinor', 'fee', '_value'])) || 0;
111	  }
112	  return m;
113	}
114	
115	function codeMap(ctx, dir) {
116	  const m = {};
117	  for (const r of rows(load(ctx, `rulebook/${dir}/carrier-codes.json`))) {
118	    const meaning = firstOf(r, ['meaning', 'kind', 'status', '_value']);
119	    m[String(firstOf(r, ['code', '_key']))] = typeof meaning === 'string' ? meaning : 'info';
120	  }
121	  return m;
122	}
123	
124	function emailOf(ctx, cust) {
125	  const r = rows(load(ctx, 'master/customers.json')).find(x => String(firstOf(x, ['customerId', '_key'])) === cust);
126	  return r ? firstOf(r, ['email']) : undefined;
127	}
128	
129	// ---------- state ----------
130	function newState(oid, p) {
131	  return {
132	    v: 1, oid, ph: 'new', p, ed: null, pol: null, D: null, cust: null, em: null, cur: null, items: [],
133	    fl: [], tot: 0, fr: null, rv: null, cl: null, ac: [], stopped: false, oend: false,
134	    os: {}, ek: {}, nt: {}, tk: {}, ob: {},
135	  };
136	}
137	
138	// Keys: one per logical effect, derived from ids only.
139	const fk = (C, F, suffix) => `${C.oid}|${F.id}|${suffix}`;
140	
141	// fitArgs: the api schema in ctx.files carries the current field names (a rename may be active).
142	// Our names missing from the schema are mapped to the schema's unclaimed names, by substring
143	// match first and by position when exactly one is left.
144	function fitArgs(w, sys, op, args) {
145	  if (!w.sch) w.sch = {};
146	  if (!(sys in w.sch)) w.sch[sys] = load(w.ctx, `api/${sys}.schema.json`) || null;
147	  const props = w.sch[sys] && w.sch[sys].ops && w.sch[sys].ops[op] && w.sch[sys].ops[op].args
148	    ? w.sch[sys].ops[op].args.properties : undefined;
149	  if (!props) return args;
150	  const have = Object.keys(args);
151	  let missing = have.filter(k => !(k in props));
152	  if (!missing.length) return args;
153	  const norm = s => s.toLowerCase().replace(/[^a-z]/g, '');
154	  let free = Object.keys(props).filter(k => !have.includes(k));
155	  const out = { ...args };
156	  for (const m of missing) {
157	    const pick = free.find(f => norm(f).includes(norm(m)) || norm(m).includes(norm(f)));
158	    if (pick === undefined) continue;
159	    out[pick] = args[m];
160	    delete out[m];
161	    free = free.filter(f => f !== pick);
162	  }
163	  missing = Object.keys(out).filter(k => !(k in props));
164	  if (missing.length === 1 && free.length === 1) {
165	    out[free[0]] = out[missing[0]];
166	    delete out[missing[0]];
167	  }
168	  return out;
169	}
170	
171	// emit: one output effect plus the tracking entry used to read its result.
172	function emit(w, sys, op, args, key, meta = {}) {
173	  const prev = w.C.ek[key];
174	  w.out.effects.push({ key, system: sys, op, args: fitArgs(w, sys, op, args) });
175	  w.C.ek[key] = { s: sys, r: null, p: false, c: null, n: prev ? (prev.n || 0) + 1 : 0, ...meta };
176	}
177	
178	// track: a tracking entry without its own effect (per-item keys of a batch reserve).
179	function track(w, key, sys) {
180	  const prev = w.C.ek[key];
181	  w.C.ek[key] = { s: sys, r: null, p: false, c: null, n: prev ? (prev.n || 0) + 1 : 0, t: 'it' };
182	}
183	
184	// settle: 'none' not emitted, 'pend' in flight, 'ok' committed, 'no' not committed.
185	function settle(w, key) {
186	  const e = w.C.ek[key];
187	  if (!e) return 'none';
188	  if (e.r === 'ok') return 'ok';
189	  if (e.r === 'err') return 'no';
190	  let st = 'pending';
191	  try { st = w.ctx.status(e.s, key); } catch { /* status unreadable: keep waiting */ }
192	  if (st === 'committed') return 'ok';
193	  if (e.r === 'unk' && st === 'not-found') return 'no';
194	  return 'pend';
195	}
196	
197	const invalidArgs = e => /invalid|renamed|400/.test(e.c || '');
198	
199	// A failure is permanent when the platform says so (retryable: false) or when it is a
200	// declined card (402, permanent by the api). Anything else may be re-issued (R4.2, R5.2).
201	const permanent = (retryable, code) => retryable === false || /declined/.test(code || '');
202	
203	// run1: emit a keyed step once; re-issue it (same key, same args) only after a 400 or an
204	// unknown outcome that did not commit. Returns 'pend' | 'ok' | 'no' | 'fail' | 'none'.
205	function run1(w, key, sys, op, args, meta, go) {
206	  const e = w.C.ek[key];
207	  if (!e) {
208	    if (!go) return 'none';
209	    emit(w, sys, op, args, key, meta);
210	    return 'pend';
211	  }
212	  const s = settle(w, key);
213	  if (s !== 'no') return s;
214	  if (e.p && !invalidArgs(e)) return 'fail';
215	  if (go && e.n < 3) {
216	    emit(w, sys, op, args, key, meta);
217	    return 'pend';
218	  }
219	  return 'fail';
220	}
221	
222	function planOf(x) {
223	  return Array.isArray(x) ? x : (x && Array.isArray(x.fulfilments) ? x.fulfilments : []);
224	}
225	
226	// itemResult: the outcome of one item of a batch reserve (a batch op keys its items, not the batch).
227	function itemResult(C, k, ent, st, err, retry) {
228	  const ie = C.ek[k];
229	  const es = ent ? ent.status : undefined;
230	  if (st === 'ok' || es === 'ok' || es === 'committed') {
231	    ie.r = 'ok';
232	    ie.p = false;
233	  } else if (st === 'error' || es === 'error') {
234	    const ec = ent && ent.error ? ent.error : err;
235	    ie.r = 'err';
236	    ie.c = ec && typeof ec === 'object' ? String(ec.code ?? '') : String(ec ?? '');
237	    const eCode = ec && typeof ec === 'object' ? String(ec.code ?? '') : String(ec ?? '');
238	    ie.p = permanent(ent ? (ent.retryable ?? (ent.error && ent.error.retryable)) : retry, eCode);
239	  } else {
240	    ie.r = 'unk';
241	  }
242	}
243	
244	// onResult: an effect.result. A batch reserve has no key of its own, so its result is matched
245	// by item key; without item detail the pending items defer to status(key).
246	function onResult(w, P) {
247	  const C = w.C;
248	  const err = P.error;
249	  const code = err && typeof err === 'object' ? String(err.code ?? '') : String(err ?? '');
250	  const retry = P.retryable ?? (err && typeof err === 'object' ? err.retryable : undefined);
251	  const perm = permanent(retry, code);
252	  const st = P.status;
253	  const e = C.ek[P.key];
254	  if (!e) {
255	    const keys = (P.items || []).map(x => x && x.key).filter(k => k && C.ek[k] && C.ek[k].t === 'it');
256	    if (keys.length) {
257	      for (const k of keys) itemResult(C, k, (P.items || []).find(x => x && x.key === k), st, err, retry);
258	    } else {
259	      for (const k of Object.keys(C.ek)) if (C.ek[k].t === 'it' && C.ek[k].r == null) C.ek[k].r = 'unk';
260	    }
261	    return;
262	  }
263	  e.r = st === 'ok' ? 'ok' : st === 'error' ? 'err' : 'unk';
264	  e.p = perm;
265	  e.c = code;
266	  if (st === 'ok' && e.t === 'al') e.plan = [P.result, P.items, P].find(x => x && typeof x === 'object' && (Array.isArray(x) || Array.isArray(x.fulfilments)));
267	  if (st === 'ok' && e.t === 'fr') {
268	    const b = [P.result, P.items, P].find(x => x && typeof x === 'object' && 'verdict' in x);
269	    if (b && ['pass', 'review', 'reject'].includes(b.verdict)) C.fr = b.verdict;
270	  }
271	}
272	
273	// ---------- inbound events ----------
274	const isPlaced = P => 'orderId' in P && 'items' in P && 'customerId' in P;
275	const isAction = P => 'orderRef' in P && 'action' in P;
276	const isCarrier = P => 'fulfilmentRef' in P && 'code' in P;
277	
278	function applyEvent(w, e) {
279	  const C = w.C;
280	  const P = e.payload || {};
281	  if (e.type === 'effect.result') return onResult(w, P);
282	  if (e.type === 'humanTask.answered') return onAnswer(C, e, P);
283	  if (e.type === 'humanTask.answerRejected' || e.type === 'humanTask.withdrawn') {
284	    if (C.rv) C.rv.reask = true;
285	    return;
286	  }
287	  if (isPlaced(P)) {
288	    if (C.cust == null) {
289	      C.cust = String(P.customerId);
290	      C.cur = String(P.currency);
291	      C.items = P.items.map(i => ({ sku: String(i.sku), qty: Number(i.qty) }));
292	      C.em = emailOf(w.ctx, C.cust) ?? null;
293	    }
294	    return;
295	  }
296	  if (isAction(P)) {
297	    const t = T(e.at);
298	    if (!C.ac.some(a => a.t === t && a.a === String(P.action))) C.ac.push({ t, a: String(P.action), u: false });
299	    return;
300	  }
301	  if (isCarrier(P)) return onCarrier(w, e, P);
302	}
303	
304	function onAnswer(C, e, P) {
305	  const rv = C.rv;
306	  if (!rv) return;
307	  const ans = P.answer ?? P.value ?? P;
308	  const d = ans && typeof ans === 'object' ? ans.decision : undefined;
309	  if ((d === 'approve' || d === 'reject') && !rv.ans) rv.ans = { d, t: T(e.at) };
310	  else if (d !== 'approve' && d !== 'reject') rv.reask = true;
311	}
312	
313	function codeMeaning(w, code) {
314	  if (!w.codes) w.codes = codeMap(w.ctx, w.C.ed);
315	  return w.codes[String(code)] || 'info';
316	}
317	
318	function onCarrier(w, e, P) {
319	  const F = w.C.fl.find(f => f.id === String(P.fulfilmentRef).trim());
320	  if (!F) return;
321	  const m = codeMeaning(w, P.code);
322	  const t = T(P.reportedAt ?? e.at);
323	  if (m === 'collected' || m === 'inTransit' || m === 'delivered') F.coll = F.coll == null ? t : Math.min(F.coll, t);
324	  if (FINAL.has(F.st) || F.xs) return;
325	  if (m === 'collectionFailed') {
326	    F.cfl = true;
327	    return failFul(w, F, 'collection');
328	  }
329	  if (m === 'collected') return setFul(w, F, 'dispatched');
330	  if (m === 'delivered') {
331	    setFul(w, F, 'dispatched');
332	    setFul(w, F, 'completed');
333	  }
334	}
335	
336	// migration (R3.5): an order already in flight. Its state is read back from the records, and the
337	// steps those records show as committed are marked so they are not issued again.
338	function rebuild(w, oid, e) {
339	  const ctx = w.ctx;
340	  const q = (table, where) => {
341	    try { return ctx.query(table, { where, limit: 1000 }) || []; } catch { return []; }
342	  };
343	  const [o] = q('orders.orders', { orderId: oid });
344	  if (!o) return false;
345	  const C = newState(oid, T(o.placedAt ?? e.at));
346	  C.cust = String(o.customerId);
347	  C.cur = String(o.currency);
348	  C.items = (o.items || []).map(i => ({ sku: String(i.sku), qty: Number(i.qty) }));
349	  C.em = emailOf(ctx, C.cust) ?? null;
350	  w.C = C;
351	  initRules(w);
352	  C.tot = Number(o.totalMinor) || 0;
353	  C.fl = q('orders.fulfilments', { orderId: oid }).map(r => {
354	    const loc = r.location ?? null;
355	    const F = {
356	      id: String(r.fulfilmentId), loc, av: loc !== null,
357	      items: (r.items || []).map(i => ({ sku: String(i.sku), qty: Number(i.qty) })),
358	      amt: Number(r.amountMinor) || 0, st: r.status, resOk: false, na: 0, fail: null, cfl: false, coll: null, xs: false,
359	    };
360	    const held = q('inventory.reservations', { fulfilmentId: F.id }).filter(x => x.status === 'active');
361	    for (const it of F.items) {
362	      if (held.some(x => x.sku === it.sku)) C.ek[fk(C, F, `r|${it.sku}`)] = { s: 'inventory', r: 'ok', p: false, c: null, n: 0, t: 'it' };
363	    }
364	    F.resOk = F.items.every(it => held.some(x => x.sku === it.sku));
365	    if (q('billing.charges', { fulfilmentId: F.id }).length) C.ek[fk(C, F, 'ch')] = { s: 'billing', r: 'ok', p: false, c: null, n: 0, t: 'ch' };
366	    const [sh] = q('carrier.shipments', { fulfilmentId: F.id });
367	    if (sh) {
368	      C.ek[fk(C, F, 'sh')] = { s: 'carrier', r: 'ok', p: false, c: null, n: 0, t: 'sh' };
369	      if (['collected', 'inTransit', 'delivered'].includes(sh.status)) F.coll = 0;
370	      if (sh.status === 'cancelled') F.xs = true;
371	      if (sh.status === 'failed') F.cfl = true;
372	    }
373	    if (F.st === 'failed') F.fail = { why: 'migrated' };
374	    return F;
375	  });
376	  C.os[o.status] = true;
377	  if (['completed', 'failed', 'cancelled', 'timedOut'].includes(o.status)) {
378	    C.oend = true;
379	    C.ph = 'end';
380	  } else if (o.status === 'customerActionRequired') {
381	    C.ph = 'wait';
382	    C.cl = C.p;
383	    C.nt[`${oid}|n|action-required|${oid}`] = true;
384	  } else if (o.status === 'processing') {
385	    C.ph = 'proc';
386	    C.cl = C.p;
387	    for (const F of C.fl) if (F.av && F.st === 'pending') setFul(w, F, 'processing');
388	  } else {
389	    C.ph = 'fraud';
390	    C.ek[`${oid}|alloc`] = { s: 'inventory', r: 'ok', p: false, c: null, n: 0, t: 'al' };
391	    C.ek[`${oid}|create`] = { s: 'orders', r: 'ok', p: false, c: null, n: 0, t: 'cr' };
392	  }
393	  return true;
394	}
395	
396	// Routing for the first tick of an instance (no carry yet). Returns an output or null.
397	function route(w, events) {
398	  for (const e of events) {
399	    const P = e.payload || {};
400	    if (e.type === 'migration') {
401	      const oid = normId(P.orderId ?? P.orderRef);
402	      if (!oid) continue;
403	      const other = openFor(w, oid)[0];
404	      if (other) return mergeInto(oid, other);
405	      if (!rebuild(w, oid, e)) return closeOut(null);
406	      return w.C.oend ? closeOut(oid) : null;
407	    }
408	    if (isPlaced(P)) {
409	      const oid = normId(P.orderId);
410	      const other = openFor(w, oid)[0];
411	      if (other) return mergeInto(oid, other);
412	      if (recorded(w, oid)) return closeOut(oid);
413	      w.C = newState(oid, T(e.at));
414	      return null;
415	    }
416	    if (isAction(P)) {
417	      const oid = normId(P.orderRef);
418	      const other = openFor(w, oid)[0];
419	      if (other) return mergeInto(oid, other);
420	      return closeOut(recorded(w, oid) ? oid : null);
421	    }
422	    if (isCarrier(P)) {
423	      const oid = orderOfFulfilment(w, String(P.fulfilmentRef).trim());
424	      const other = oid ? openFor(w, oid)[0] : undefined;
425	      if (other) return mergeInto(oid, other);
426	      return closeOut(oid);
427	    }
428	  }
429	  return closeOut(null);
430	}
431	
432	function openFor(w, oid) {
433	  let l = [];
434	  try { l = w.ctx.instances({ subject: oid }) || []; } catch { l = []; }
435	  return l.map(x => (typeof x === 'string' ? x : x?.instance ?? x?.id)).filter(x => x && x !== w.instance);
436	}
437	
438	function recorded(w, oid) {
439	  try { return (w.ctx.query('orders.orders', { where: { orderId: oid }, limit: 1 }) || []).length > 0; } catch { return false; }
440	}
441	
442	function orderOfFulfilment(w, fid) {
443	  try {
444	    const r = w.ctx.query('orders.fulfilments', { where: { fulfilmentId: fid }, limit: 1 }) || [];
445	    return r[0] ? normId(r[0].orderId) : null;
446	  } catch { return null; }
447	}
448	
449	const emptyOut = () => ({ decisions: { subject: null }, effects: [], obligations: { upsert: [], cancel: [] }, humanTasks: [] });
450	const mergeInto = (oid, into) => ({ ...emptyOut(), decisions: { subject: oid }, merge: { into }, carry: { v: 1, merged: true } });
451	const closeOut = oid => ({ ...emptyOut(), decisions: { subject: oid }, close: true, carry: { v: 1, closed: true } });
452	
453	function initRules(w) {
454	  const C = w.C;
455	  const ed = pickEdition(w.ctx, C.p);
456	  C.ed = ed ? ed.dir : null;
457	  const pol = (C.ed && load(w.ctx, `rulebook/${C.ed}/policy.json`)) || {};
458	  C.pol = { fh: Number(pol.fraudReviewHours) || 0, ca: Number(pol.customerActionHours) || 0 };
459	  C.D = C.p + C.pol.ca * 60 * MIN;
460	}
461	
462	// ---------- fulfilments and order statuses ----------
463	function buildFulfilments(w, plan) {
464	  const C = w.C;
465	  const price = priceMap(w.ctx);
466	  const fee = C.ed ? feeMap(w.ctx, C.ed) : {};
467	  C.fl = plan.map(f => {
468	    const loc = f.location ?? null;
469	    const av = loc !== null;
470	    const items = (f.items || []).map(i => ({ sku: String(i.sku), qty: Number(i.qty) }));
471	    const amt = items.reduce((s, i) => s + i.qty * (price[i.sku] || 0), 0) + (av ? (fee[loc] || 0) : 0);
472	    return { id: String(f.fulfilmentId), loc, av, items, amt, st: av ? 'pending' : 'unavailable',
473	      resOk: false, na: 0, fail: null, cfl: false, coll: null, xs: false };
474	  });
475	  C.tot = C.fl.reduce((s, F) => s + F.amt, 0);
476	}
477	
478	// R1.1 record: the order and its fulfilments as allocated, with the amounts of R1.2.
479	function createArgs(C) {
480	  return {
481	    orderId: C.oid, customerId: C.cust, placedAt: isoAms(C.p), currency: C.cur, items: C.items,
482	    fulfilments: C.fl.map(F => ({ fulfilmentId: F.id, location: F.loc, items: F.items, amountMinor: F.amt })),
483	    totalMinor: C.tot,
484	  };
485	}
486	
487	function setFul(w, F, s) {
488	  if (F.st === s || FINAL.has(F.st) || FUL_ORDER.indexOf(s) <= FUL_ORDER.indexOf(F.st)) return;
489	  F.st = s;
490	  emit(w, 'orders', 'setStatus', { orderId: w.C.oid, fulfilmentId: F.id, status: s }, `${w.C.oid}|f|${F.id}|${s}`);
491	}
492	
493	function setOrd(w, s) {
494	  const C = w.C;
495	  if (C.os[s] || C.oend) return;
496	  C.os[s] = true;
497	  if (['completed', 'failed', 'cancelled', 'timedOut'].includes(s)) C.oend = true;
498	  emit(w, 'orders', 'setStatus', { orderId: C.oid, fulfilmentId: null, status: s }, `${C.oid}|o|${s}`);
499	}
500	
501	function notify(w, template, about, text, suffix = '') {
502	  const C = w.C;
503	  const key = `${C.oid}|n|${template}|${about}${suffix}`;
504	  if (C.nt[key]) return;
505	  C.nt[key] = true;
506	  emit(w, 'notify', 'send', { to: C.em || C.cust || 'unknown', about, template, text }, key);
507	}
508	
509	function failFul(w, F, why) {
510	  if (F.fail || FINAL.has(F.st)) return;
511	  F.fail = { why };
512	  setFul(w, F, 'failed');
513	  notify(w, 'fulfilment-failed', F.id, `Fulfilment ${F.id} of order ${w.C.oid} could not be completed (${why}).`);
514	}
515	
516	// R6.1 (also R6.2 once the order is stopped): nothing of the order is left to ship.
517	function cancelOrder(w, reason) {
518	  const C = w.C;
519	  for (const F of C.fl) if (!FINAL.has(F.st)) setFul(w, F, 'cancelled');
520	  setOrd(w, 'cancelled');
521	  notify(w, 'order-cancelled', C.oid, `Your order ${C.oid} was cancelled (${reason}).`);
522	  C.stopped = true;
523	  C.ph = 'end';
524	}
525	
526	// R3.2: nothing counted by D.
527	function timeOut(w) {
528	  const C = w.C;
529	  for (const F of C.fl) if (!FINAL.has(F.st)) setFul(w, F, 'cancelled');
530	  setOrd(w, 'timedOut');
531	  notify(w, 'order-timed-out', C.oid, `Your order ${C.oid} timed out: no change was requested in time.`);
532	  C.ph = 'end';
533	}
534	
535	function startProcessing(w) {
536	  const C = w.C;
537	  setOrd(w, 'processing');
538	  for (const F of C.fl) if (F.av) setFul(w, F, 'processing');
539	  C.ph = 'proc';
540	}
541	
542	// R2 / R2.2: the order is cleared at t.
543	function clearOrder(w, t) {
544	  const C = w.C;
545	  C.cl = t;
546	  if (C.fl.some(F => !F.av)) {
547	    setOrd(w, 'customerActionRequired');
548	    notify(w, 'action-required', C.oid, `Some items of order ${C.oid} are unavailable. Reply by ${isoAms(C.D)} to amend or cancel.`);
549	    C.ph = 'wait';
550	  } else {
551	    startProcessing(w);
552	  }
553	}
554	
555	// R3.2 amend: drop the unavailable fulfilments; the rest is ready at t.
556	function amend(w) {
557	  const C = w.C;
558	  for (const F of C.fl) if (!F.av) setFul(w, F, 'cancelled');
559	  if (!C.fl.some(F => F.av)) return cancelOrder(w, 'nothing-available');
560	  startProcessing(w);
561	}
562	
563	function openTask(w) {
564	  const C = w.C;
565	  const rv = C.rv;
566	  const id = `${C.oid}-rv${rv.n}`;
567	  if (C.tk[id]) return;
568	  C.tk[id] = true;
569	  w.out.humanTasks.push({
570	    id, kind: 'fraudReview', role: 'fraudAnalyst', subject: C.oid,
571	    question: `Fraud review of order ${C.oid}: approve or reject.`,
572	    answerSchema: {
573	      type: 'object', required: ['decision'], additionalProperties: false,
574	      properties: { decision: { type: 'string', enum: ['approve', 'reject'] } },
575	    },
576	    dueAt: isoAms(rv.dl), onTimeout: 'cancel',
577	  });
578	}
579	
580	function openReview(w) {
581	  const C = w.C;
582	  C.rv = { dl: w.now + C.pol.fh * 60 * MIN, n: 1, ans: null, reask: false };
583	  C.ph = 'review';
584	  openTask(w);
585	}
586	
587	// Customer cancels not yet used, for the pre-clearing rules (R6.4).
588	function takeCancel(C) {
589	  let hit = false;
590	  for (const a of C.ac) if (!a.u && a.a === 'cancel') { a.u = true; hit = true; }
591	  return hit;
592	}
593	
594	const collectedBy = (C, t) => C.fl.some(F => F.coll != null && F.coll <= t);
595	
596	// ---------- phases of the order ----------
597	// ph: new -> alloc -> create -> fraud -> (review) -> wait? -> proc -> end
598	function phaseStep(w) {
599	  const C = w.C;
600	  const now = w.now;
601	  if (C.ph === 'new') {
602	    C.ph = 'alloc';
603	    emit(w, 'inventory', 'allocate', { orderId: C.oid }, `${C.oid}|alloc`, { t: 'al' });
604	    return;
605	  }
606	  if (C.ph === 'alloc') {
607	    const e = C.ek[`${C.oid}|alloc`];
608	    if (!e || e.r !== 'ok' || !e.plan) return;
609	    buildFulfilments(w, planOf(e.plan));
610	    delete e.plan;
611	    C.ph = 'create';
612	    run1(w, `${C.oid}|create`, 'orders', 'create', createArgs(C), { t: 'cr' }, true);
613	    return;
614	  }
615	  if (C.ph === 'create') {
616	    if (run1(w, `${C.oid}|create`, 'orders', 'create', createArgs(C), { t: 'cr' }, true) === 'ok') C.ph = 'fraud';
617	    return;
618	  }
619	  if (C.ph === 'fraud') {
620	    const frK = `${C.oid}|fr`;
621	    if (!C.ek[frK]) emit(w, 'fraud', 'check', { orderId: C.oid }, frK, { t: 'fr' });
622	    if (!C.fr) {
623	      if (takeCancel(C)) cancelOrder(w, 'customer');
624	      return;
625	    }
626	    if (C.fr === 'reject') return cancelOrder(w, 'fraud');
627	    if (C.fr === 'review') return openReview(w);
628	    return clearOrder(w, C.p);
629	  }
630	  if (C.ph === 'review') {
631	    const rv = C.rv;
632	    if (takeCancel(C)) return cancelOrder(w, 'customer');
633	    if (rv.ans && rv.ans.t <= rv.dl) {
634	      if (rv.ans.d === 'reject') return cancelOrder(w, 'fraud');
635	      return clearOrder(w, rv.ans.t);
636	    }
637	    if (now > rv.dl) return cancelOrder(w, 'fraud-review-timeout');
638	    if (rv.reask) {
639	      rv.reask = false;
640	      rv.n += 1;
641	      openTask(w);
642	    }
643	    return;
644	  }
645	  if (C.ph === 'wait') {
646	    const D = C.D;
647	    const due = C.ac.filter(a => !a.u && a.t <= D).sort((x, y) => x.t - y.t);
648	    const first = due.find(a => a.a === 'amend' || a.a === 'cancel');
649	    for (const a of due) a.u = true;
650	    if (first) return first.a === 'cancel' ? cancelOrder(w, 'customer') : amend(w);
651	    if (now > D) timeOut(w);
652	    return;
653	  }
654	  if (C.ph === 'proc') {
655	    const cancels = C.ac.filter(a => !a.u && a.a === 'cancel').sort((x, y) => x.t - y.t);
656	    for (const a of C.ac) if (a.a === 'amend') a.u = true;
657	    for (const a of cancels) {
658	      a.u = true;
659	      if (collectedBy(C, a.t)) {
660	        notify(w, 'cancel-refused', C.oid, `Your order ${C.oid} can no longer be cancelled: it has been collected.`, `|${a.t}`);
661	      } else {
662	        return cancelOrder(w, 'customer');
663	      }
664	    }
665	  }
666	}
667	
668	// ---------- R4.2 forward steps (one saga per fulfilment) ----------
669	function stepReserve(w, F, go) {
670	  const C = w.C;
671	  const ik = sku => fk(C, F, `r|${sku}`);
672	  const rs = F.items.map(i => ({ sku: i.sku, qty: i.qty, s: settle(w, ik(i.sku)) }));
673	  if (rs.some(x => x.s === 'pend')) return;
674	  if (rs.every(x => x.s === 'ok')) {
675	    F.resOk = true;
676	    return;
677	  }
678	  if (rs.some(x => x.s === 'no' && C.ek[ik(x.sku)].p && !invalidArgs(C.ek[ik(x.sku)]))) return failFul(w, F, 'reserve');
679	  if (!go) return;
680	  if (F.na >= 4) return failFul(w, F, 'reserve');
681	  const need = rs.filter(x => x.s !== 'ok');
682	  F.na += 1;
683	  for (const x of need) track(w, ik(x.sku), 'inventory');
684	  // A batch carries no top-level key: each item is keyed (R4.2, api/inventory.schema.json).
685	  w.out.effects.push({
686	    system: 'inventory', op: 'reserve',
687	    args: fitArgs(w, 'inventory', 'reserve', {
688	      orderId: C.oid, fulfilmentId: F.id, location: F.loc, items: need.map(x => ({ key: ik(x.sku), sku: x.sku, qty: x.qty })),
689	    }),
690	  });
691	}
692	
693	function forward(w, F) {
694	  const C = w.C;
695	  const go = !C.stopped && !F.fail;
696	  if (!F.resOk) {
697	    stepReserve(w, F, go);
698	    if (!F.resOk) return;
699	  }
700	  if (!go) return;
701	  const c = run1(w, fk(C, F, 'ch'), 'billing', 'charge', {
702	    orderId: C.oid, fulfilmentId: F.id, customerId: C.cust, amountMinor: F.amt, currency: C.cur,
703	  }, { t: 'ch' }, true);
704	  if (c === 'fail') return failFul(w, F, 'charge');
705	  if (c !== 'ok') return;
706	  const s = run1(w, fk(C, F, 'sh'), 'carrier', 'create', {
707	    orderId: C.oid, fulfilmentId: F.id, location: F.loc, ref: F.id,
708	  }, { t: 'sh' }, true);
709	  if (s === 'fail') failFul(w, F, 'ship');
710	}
711	
712	// R5.1 compensation in reverse order: shipment, then refund, then releases. Each step
713	// waits for the one before it to settle; a step that never committed is not undone.
714	function compensate(w, F) {
715	  const C = w.C;
716	  const xs = fk(C, F, 'xs'), sh = fk(C, F, 'sh'), ch = fk(C, F, 'ch'), rf = fk(C, F, 'rf');
717	  if (settle(w, sh) === 'pend') return;
718	  if (settle(w, sh) === 'ok' && !F.cfl && !C.ek[xs]) {
719	    F.xs = true;
720	    emit(w, 'carrier', 'cancel', { orderId: C.oid, fulfilmentId: F.id }, xs, { t: 'xs' });
721	  }
722	  if (C.ek[xs] && settle(w, xs) === 'pend') return;
723	  const chS = settle(w, ch);
724	  if (chS === 'pend') return;
725	  if (chS === 'ok' && !C.ek[rf]) {
726	    emit(w, 'billing', 'refund', { orderId: C.oid, fulfilmentId: F.id, amountMinor: F.amt }, rf, { t: 'rf' });
727	  }
728	  if (C.ek[rf] && settle(w, rf) === 'pend') return;
729	  for (const sku of [...new Set(F.items.map(i => i.sku))]) {
730	    const s = settle(w, fk(C, F, `r|${sku}`));
731	    if (s === 'pend') return;
732	    const rl = fk(C, F, `rl|${sku}`);
733	    if (s === 'ok' && !C.ek[rl]) emit(w, 'inventory', 'release', { orderId: C.oid, fulfilmentId: F.id, sku }, rl, { t: 'rl' });
734	  }
735	}
736	
737	function advance(w) {
738	  for (let i = 0; i < 6; i++) {
739	    const before = w.C.ph;
740	    phaseStep(w);
741	    if (w.C.ph === before) break;
742	  }
743	  const C = w.C;
744	  if (C.ph === 'proc') for (const F of C.fl) if (F.av) forward(w, F);
745	  for (const F of C.fl) if (F.av && (F.fail || C.stopped) && F.st !== 'completed') compensate(w, F);
746	  if (C.ph === 'proc' && C.fl.length && C.fl.every(F => FINAL.has(F.st))) {
747	    setOrd(w, C.fl.some(F => F.st === 'completed') ? 'completed' : C.fl.some(F => F.st === 'failed') ? 'failed' : 'cancelled');
748	    C.ph = 'end';
749	  }
750	}
751	
752	// ---------- obligations (wake-ups at deadlines; each fires one minute after its deadline) ----------
753	function obligations(w) {
754	  const C = w.C;
755	  const want = {};
756	  if (C.ph === 'review' && C.rv) want[`${C.oid}-review-deadline`] = { due: C.rv.dl + MIN, on: 'fraudReviewDeadline' };
757	  if (C.ph === 'wait') want[`${C.oid}-customer-deadline`] = { due: C.D + MIN, on: 'customerDeadline' };
758	  for (const [id, o] of Object.entries(want)) {
759	    if (C.ob[id] === o.due) continue;
760	    C.ob[id] = o.due;
761	    w.out.obligations.upsert.push({ id, kind: 'deadline', anchor: isoAms(C.p), dueAt: isoAms(o.due), onDue: o.on });
762	  }
763	  for (const id of Object.keys(C.ob)) {
764	    if (want[id]) continue;
765	    delete C.ob[id];
766	    w.out.obligations.cancel.push(id);
767	  }
768	}
769	
770	function finish(w) {
771	  const C = w.C;
772	  obligations(w);
773	  const pending = Object.entries(C.ek).some(([k, e]) => e.r == null || (e.r === 'unk' && settle(w, k) === 'pend'));
774	  w.out.decisions = { subject: C.oid };
775	  w.out.carry = C;
776	  if (C.ph === 'end' && !pending) w.out.close = true;
777	  return w.out;
778	}
779	
780	// ---------- the arm ----------
781	function tick(input, ctx) {
782	  const w = {
783	    C: input.carry && typeof input.carry === 'object' ? input.carry : null,
784	    out: emptyOut(), ctx, now: T(input.now), instance: input.instance, codes: null,
785	  };
786	  const events = input.events || [];
787	  if (!w.C) {
788	    const early = route(w, events);
789	    if (early) return early;
790	    initRules(w);
791	  }
792	  for (const e of events) applyEvent(w, e);
793	  advance(w);
794	  return finish(w);
795	}
796	
797	export function createSolver() {
798	  return { id: 'solver', tick };
799	}
800

