    const P = e.payload || {};
    if (e.type === 'migration') {
      const oid = normId(P.orderId ?? P.orderRef);
      if (!oid) continue;
      const other = openFor(w, oid)[0];
      if (other) return mergeInto(oid, other);
      if (!rebuild(w, oid, e)) return closeOut(null);
      return w.C.oend ? closeOut(oid) : null;
    }

